declaredSchema.of:
function validAffix(a) {
  if (!a || typeof a !== 'object') return false;
  // AUDIT LW-II-2 S8: the kind's OWN row - an id Object.prototype answers ('constructor') passed as a kind, and the line
  // below threw on its range (the item law, the judge's worth and the patrons' reckoning with it)
  const k = Object.hasOwn(AFFIX_KINDS, a.id) ? AFFIX_KINDS[a.id] : null;
  if (!k) return false;
  if (k.params ? !k.params.includes(a.param) : a.param !== undefined) return false;
  const max = AFFIX_RANGES[a.id].legendary[1];
  return Number.isInteger(a.value) && a.value >= 1 && a.value <= max;
}

declaredSchema.check:
function validSigil(s) {
  if (!s || typeof s !== 'object' || Array.isArray(s)) return false;
  if (!(Number.isInteger(s.party) && s.party >= 1 && s.party <= PARTY_MAX)) return false;
  if (!(Number.isInteger(s.xp) && s.xp >= 0 && s.xp <= SIGIL_XP_MAX)) return false;
  const hasPower = s.power !== undefined,
    hasSet = s.set !== undefined;
  if (!hasPower && !hasSet) return false;
  if (hasPower && !validPower(s.power)) return false;
  if (hasSet && !SIGIL_SET_IDS.includes(s.set)) return false;
  return true;
}
